import React, { useState } from 'react';
import { SafeAreaView, View, Text, Button, StyleSheet } from 'react-native';
import HomeScreen from './src/screens/HomeScreen';
import LoginScreen from './src/screens/LoginScreen';
import RegisterScreen from './src/screens/RegisterScreen';
import Navbar from './src/components/Navbar';

export default function App() {
  const [route, setRoute] = useState('home');
  const [user, setUser] = useState(null);

  const navigate = (r) => setRoute(r);

  const handleLoginSuccess = (u) => {
    setUser(u);
    setRoute('home');
  };

  return (
    <SafeAreaView style={{ flex: 1 }}>
      <Navbar user={user} onAuthClick={(mode) => navigate(mode)} setPage={navigate} />
      {route === 'home' && <HomeScreen user={user} onNavigate={navigate} />}
      {route === 'login' && <LoginScreen onSuccess={handleLoginSuccess} onBack={() => setRoute('home')} />}
      {route === 'register' && <RegisterScreen onSuccess={handleLoginSuccess} onBack={() => setRoute('home')} />}
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({});
